CTX = '(supplement*[tiab] OR "dietary supplements"[mh] OR oral[tiab] OR capsule*[tiab] OR tablet*[tiab] OR extract[tiab])'

def S(key, label, terms, topic, outcomes, ctx=True, mesh=(), title_exclude=()):
    q = " OR ".join([f'"{m}"[mh]' for m in mesh] + [f'"{t}"[tiab]' if " " in t else f"{t}[tiab]" for t in terms])
    search = f"({q})" + (f" AND {CTX}" if ctx else "")
    return dict(key=key, label=label, search=search, topic_patterns=topic,
                title_exclude=list(title_exclude), outcomes={o: O[o] for o in outcomes}, analyze=list(outcomes))

